using System;using System.Collections.Generic;using System.Threading.Tasks;
// In-process owner authority. The stage callback MUST read the authenticated
// parent transition under its writer fence; it is never supplied by the WebView.
internal sealed class UsbHidAdmissionNativeAuthority:SentinelHidAdmission.UsbExactBlockTransaction.INativeAuthority {
 readonly UsbHidAdmissionPolicy.Request selected;readonly UsbAdmissionAuthorization.Proof proof;readonly Func<UsbHidAdmissionPolicy.Stage?> stage;readonly Witness captured;
 UsbHidAdmissionNativeAuthority(UsbHidAdmissionPolicy.Request request,UsbAdmissionAuthorization.Proof verified,Func<UsbHidAdmissionPolicy.Stage?> phase,Witness witness){selected=request;proof=verified;stage=phase;captured=witness;}
 internal static UsbAdmissionAuthorization.Request Binding(UsbHidAdmissionPolicy.Request q){if(q==null)throw new ArgumentNullException("q");string action=q.Action=="activate"?"initial-arm":q.Action=="deactivate"?"release":q.Action=="allow"?"approve":q.Action=="block"?"revoke":null;return new UsbAdmissionAuthorization.Request(q.Before.OwnerSid,q.Before.Generation,q.TopologyHash,action,q.Digest);}
 internal static async Task<UsbHidAdmissionNativeAuthority> Verify(IntPtr window,UsbHidAdmissionPolicy.Request q,Func<UsbHidAdmissionPolicy.Stage?> authenticatedStage){if(q==null||authenticatedStage==null)throw new ArgumentNullException();bool release=q.Action=="deactivate";var inventory=release?null:UsbAdmissionInventory.Collect(q.TopologyHash);Witness witness=null;if(release)CheckRelease(q);else{CheckBefore(q.Before,inventory,q.TopologyHash);witness=Capture(q,inventory);}CheckInventory(q,witness,inventory,null);var verified=await UsbAdmissionAuthorization.Verify(window,Binding(q));if(verified==null)return null;if(release)CheckRelease(q);else CheckBefore(q.Before,UsbAdmissionInventory.Collect(q.TopologyHash),q.TopologyHash);return new UsbHidAdmissionNativeAuthority(q,verified,authenticatedStage,witness);}
 void Same(UsbHidAdmissionPolicy.Request q){if(!object.ReferenceEquals(q,selected))throw new InvalidOperationException("HID request changed");}
 public void ConsumeOwnerProof(UsbHidAdmissionPolicy.Request q){Same(q);var phase=stage();if(phase.HasValue)throw new InvalidOperationException("HID pending decision present");proof.Consume(Binding(q));}
  public void VerifyFreshExternalScope(UsbHidAdmissionPolicy.Request q){Same(q);var phase=stage();bool post=phase==UsbHidAdmissionPolicy.Stage.Applied||phase==UsbHidAdmissionPolicy.Stage.PolicyVerified||phase==UsbHidAdmissionPolicy.Stage.Committed;CheckInventory(q,captured,q.Action=="deactivate"?null:UsbAdmissionInventory.Collect(post?null:q.TopologyHash),phase);}
 internal static void CheckInventory(UsbHidAdmissionPolicy.Request q,Witness witness,UsbAdmissionInventory.Result inventory,UsbHidAdmissionPolicy.Stage? phase){if(q==null)throw new ArgumentNullException("q");if(q.Action=="deactivate"){CheckRelease(q);if(phase.HasValue&&phase!=UsbHidAdmissionPolicy.Stage.Prepared&&phase!=UsbHidAdmissionPolicy.Stage.RecoveryArmed&&phase!=UsbHidAdmissionPolicy.Stage.Applied&&phase!=UsbHidAdmissionPolicy.Stage.PolicyVerified&&phase!=UsbHidAdmissionPolicy.Stage.Committed)throw new InvalidOperationException("HID release phase refused");return;}if(!phase.HasValue||phase==UsbHidAdmissionPolicy.Stage.Prepared||phase==UsbHidAdmissionPolicy.Stage.RecoveryArmed){CheckBefore(q.Before,inventory,q.TopologyHash);var targets=new HashSet<string>(q.Targets,StringComparer.OrdinalIgnoreCase);foreach(var c in inventory.Preflight.Candidates)if(c.Category=="external_approval_required")targets.Remove(c.Instance);if(targets.Count!=0)throw new InvalidOperationException("HID request target missing");}else if(phase==UsbHidAdmissionPolicy.Stage.Applied||phase==UsbHidAdmissionPolicy.Stage.PolicyVerified||phase==UsbHidAdmissionPolicy.Stage.Committed)CheckAfter(q,witness,inventory);else throw new InvalidOperationException("HID authority phase refused");}
 // Release restores authenticated policy only; blocked-device visibility is not authority.
 internal static void CheckRelease(UsbHidAdmissionPolicy.Request q){if(q==null||q.Action!="deactivate"||!q.Before.Active||q.After.Active||q.Targets.Length!=0||q.TopologyHash!=q.Before.Digest)throw new InvalidOperationException("HID release scope refused");}
 static Dictionary<string,string> Evidence(UsbAdmissionInventory.Result inventory,bool strict){
  if(inventory==null||!inventory.Complete||inventory.Preflight==null||inventory.Preflight.Candidates==null||inventory.Subjects==null||inventory.Preflight.Unresolved!=0||(strict?inventory.Preflight.State!="review_required":inventory.Preflight.State!="review_required"&&inventory.Preflight.State!="refused_no_usb_hid"))throw new InvalidOperationException("Fresh HID evidence required");
  var result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(var c in inventory.Preflight.Candidates){if(c==null||string.IsNullOrEmpty(c.Instance)||(c.Category!="required_safety_candidate"&&c.Category!="external_approval_required")||result.ContainsKey(c.Instance))throw new InvalidOperationException("Ambiguous HID classification");UsbAdmissionPreflight.Input input=null;int matches=0;foreach(var s in inventory.Subjects){if(s==null||s.Input==null)throw new InvalidOperationException("Invalid HID source");if(string.Equals(s.Input.Instance,c.Instance,StringComparison.OrdinalIgnoreCase)){input=s.Input;matches++;}}if(matches!=1||!input.Complete||input.ParentChain==null||input.ParentChain.Length<2||input.LocationPaths==null||input.CompatibleIds==null)throw new InvalidOperationException("Incomplete HID source");
   result.Add(c.Instance,c.Category+"\n"+input.DeviceClass+"\n"+input.TransportService+"\n"+input.ConnectorState+"\n"+input.ConnectorMatches+"\n"+input.ConnectorPartial+"\n"+input.TouchpadUsage+"\n"+string.Join("\n",input.ParentChain).ToUpperInvariant()+"\n--locations--\n"+string.Join("\n",input.LocationPaths).ToUpperInvariant()+"\n--compatible--\n"+string.Join("\n",input.CompatibleIds).ToUpperInvariant());}
  if(inventory.Subjects.Length!=result.Count)throw new InvalidOperationException("Unexpected HID sources");return result;
 }
 internal static void CheckBefore(UsbHidAdmissionPolicy.Snapshot before,UsbAdmissionInventory.Result inventory,string topology){if(before==null||inventory==null||inventory.Preflight==null||inventory.Preflight.TopologyToken!=topology)throw new InvalidOperationException("HID topology changed");var evidence=Evidence(inventory,true);var safety=new HashSet<string>(before.InternalSafety,StringComparer.OrdinalIgnoreCase);foreach(var c in inventory.Preflight.Candidates){if((c.Category=="required_safety_candidate")!=safety.Contains(c.Instance))throw new InvalidOperationException("HID safety receipt classification changed");}foreach(string id in safety)if(!evidence.ContainsKey(id))throw new InvalidOperationException("HID safety input missing");}
 internal sealed class Witness {internal readonly string RequestDigest;readonly Dictionary<string,string> before;internal IEnumerable<string> Ids{get{return before.Keys;}}internal bool Find(string id,out string value){return before.TryGetValue(id,out value);}internal Witness(string digest,Dictionary<string,string> evidence){RequestDigest=digest;before=new Dictionary<string,string>(evidence,StringComparer.OrdinalIgnoreCase);}}
 internal static Witness Capture(UsbHidAdmissionPolicy.Request q,UsbAdmissionInventory.Result inventory){CheckBefore(q.Before,inventory,q.TopologyHash);return new Witness(q.Digest,Evidence(inventory,true));}
 internal static void CheckAfter(UsbHidAdmissionPolicy.Request q,Witness witness,UsbAdmissionInventory.Result inventory){if(q==null||witness==null||q.Digest!=witness.RequestDigest)throw new InvalidOperationException("HID witness request changed");var current=Evidence(inventory,false);foreach(var pair in current){string prior;if(!witness.Find(pair.Key,out prior)||prior!=pair.Value)throw new InvalidOperationException("HID function identity changed");}
  var mayDisappear=new HashSet<string>(StringComparer.OrdinalIgnoreCase);if(q.Action=="activate"){var approved=new HashSet<string>(q.After.ExternalApprovals,StringComparer.OrdinalIgnoreCase);var safety=new HashSet<string>(q.After.InternalSafety,StringComparer.OrdinalIgnoreCase);foreach(string id in witness.Ids)if(!approved.Contains(id)&&!safety.Contains(id))mayDisappear.Add(id);}else if(q.Action=="block")foreach(string id in q.Targets)mayDisappear.Add(id);
  foreach(string id in witness.Ids)if(!current.ContainsKey(id)&&!mayDisappear.Contains(id))throw new InvalidOperationException("HID non-target input missing");foreach(string id in q.After.InternalSafety)if(!current.ContainsKey(id))throw new InvalidOperationException("HID protected input missing");
 }
}

